use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = String::new();
    let mut current = String::new();
    let mut max_run = 0;

    for c in input.as_str().chars() {
        if c.is_alphanumeric() {
            current.push(c);
            max_run += 1;
        } else {
            if max_run > 0 {
                result.push('-');
            }
            result.push_str(&current);
            current.clear();
            max_run = 0;
        }
    }

    if max_run > 0 {
        result.push('-');
    }
    result.push_str(&current);

    serde_json::Value::from_str(result).unwrap()
}
